package ca.yorku.eecs3311.coursepilot.application.agent; import org.springframework.stereotype.Component; import java.util.*; @Component public class IntentAnalyzer {public AgentIntent analyze(String request){String x=Objects.toString(request,"").toLowerCase(Locale.ROOT);if(x.contains("study plan")||x.contains("schedule")||x.contains("plan my"))return AgentIntent.STUDY_PLAN_CREATION;if(x.contains("quiz")||x.contains("test me"))return AgentIntent.QUIZ_GENERATION;if(x.contains("summar"))return AgentIntent.SUMMARY_GENERATION;if(x.contains("weak")||x.contains("struggl"))return AgentIntent.WEAK_TOPIC_SUPPORT;if(x.contains("history")||x.contains("recent"))return AgentIntent.HISTORY_REVIEW;if(x.contains("search")||x.contains("find "))return AgentIntent.COURSE_SEARCH;if(x.contains("next")||x.contains("recommend"))return AgentIntent.NEXT_STEP;return AgentIntent.PROGRESS_REVIEW;}}
